import { Separator as AriaSeparator } from "react-aria-components";
import type { SeparatorProps as AriaSeparatorProps } from "react-aria-components";
import type { Ref } from "react";
import "./Separator.css";

export interface SeparatorProps extends Omit<AriaSeparatorProps, "className"> {
  /**
   * `band` is a thick neutral strip between sections of a page; `line` is a rule. A band is drawn only for a horizontal separator: a vertical one
   * stays a line, since a vertical band has no use. Bleeding the band past the page's inset is the
   * screen's layout, not the Separator's.
   *
   * @default "line"
   */
  variant?: "line" | "band";
  /**
   * A rule that only punctuates: the items it sits between are already parted by spacing, so it
   * conveys no grouping. Hidden from assistive tech and drawn in the light decorative edge rather
   * than the boundary colour a Separator otherwise carries (WCAG 1.4.11 asks nothing of trim).
   *
   * @default false
   */
  isDecorative?: boolean;
  className?: string;
  /**
   * Passed to the underlying separator DOM element. React Aria renders a horizontal
   * separator as an `<hr>` and swaps to a `<div>` only for `orientation="vertical"`
   * (`react-aria-components/dist/private/Separator.mjs`), so the ref can be either —
   * the default (horizontal) case is the `<hr>`.
   */
  ref?: Ref<HTMLHRElement | HTMLDivElement>;
}

export function Separator({
  variant = "line",
  isDecorative = false,
  orientation = "horizontal",
  className,
  ...props
}: SeparatorProps) {
  if (isDecorative)
    return (
      <div
        aria-hidden="true"
        data-orientation={orientation}
        data-variant={variant}
        data-decorative=""
        className={className ? `sd-separator ${className}` : "sd-separator"}
        ref={props.ref as Ref<HTMLDivElement>}
      />
    );
  return (
    <AriaSeparator
      {...props}
      orientation={orientation}
      data-orientation={orientation}
      data-variant={variant}
      className={className ? `sd-separator ${className}` : "sd-separator"}
    />
  );
}

.sd-separator {
  flex-shrink: 0;
  /* RAC renders horizontal Separator as <hr>; kill the UA inset border so only
     the flat --sd-separator-background bar shows (reset.css doesn't cover this). */
  border: none;
  background: var(--sd-separator-background);
}

/* Punctuation, not a boundary: the light decorative edge. */
.sd-separator[data-decorative] {
  background: var(--sd-separator-decorative-background);
}

.sd-separator[data-orientation="horizontal"] {
  width: 100%;
  height: var(--sd-separator-size);
}

/* band: a thick neutral strip between page sections; a vertical separator stays a line. It parts
   the PAGE, so it runs edge to edge of its frame rather than stopping at the content's inset: one
   frame width (`100cqi`, the nearest inline-size container, which AppShell's panel is; the viewport
   where there is none), pulled back by the difference between the two. Centred content is assumed,
   which a page's sections are. */
.sd-separator[data-orientation="horizontal"][data-variant="band"] {
  width: 100cqi;
  margin-inline-start: calc(50% - 50cqi);
  height: var(--sd-separator-band-size);
  background: var(--sd-separator-band-background);
}

.sd-separator[data-orientation="vertical"] {
  width: var(--sd-separator-size);
  /* In a flex row (e.g. Toolbar) stretch to the line's height. `height: 100%` collapses
     when the parent has no definite height, so it would fall back to min-height (a short
     floating bar) — align-self:stretch is what actually fills the row. min-height is the
     fallback for non-flex contexts. */
  align-self: stretch;
  min-height: var(--sd-separator-min-height-vertical);
}
